import ffmpegPath from 'ffmpeg-static'
import ffprobeStatic from 'ffprobe-static'

/**
 * Returns absolute path to FFmpeg binary.
 * Priority:
 *   1. FFMPEG_PATH env var
 *   2. ffmpeg-static npm package
 *   3. 'ffmpeg' system binary fallback
 */
export function getFFmpegPath(): string {
  if (process.env.FFMPEG_PATH) {
    return process.env.FFMPEG_PATH
  }
  if (typeof ffmpegPath === 'string' && ffmpegPath) {
    return ffmpegPath
  }
  return 'ffmpeg'
}

/**
 * Returns absolute path to FFprobe binary.
 * Priority:
 *   1. FFPROBE_PATH env var
 *   2. ffprobe-static npm package
 *   3. 'ffprobe' system binary fallback
 */
export function getFFprobePath(): string {
  if (process.env.FFPROBE_PATH) {
    return process.env.FFPROBE_PATH
  }
  if (ffprobeStatic?.path) {
    return ffprobeStatic.path
  }
  return 'ffprobe'
}
